SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (230::BIGINT, 'El profe a veces explica muy rápido el uso de los softwares y las normas, pero siempre resuelve cualquier duda. Hace el curso relativamente más sencillo que otros profes y califica justo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '87159d43635c5d5c8fc1b0d8d2dc8723cca55f3189c3bfd3d428d3319b087f6b'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Explica bien y es excelente con las herramientas de software. Explica un poco rápido pero dispuesto a resolver dudas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c3cf486b151784b2d7417da056961f2fc36227ff7f347350a362ea4caa00fead'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Por la opiniones y voces externas creí que iba a ser un excelente profesor, perfecto para DT, pero al final no fue tanto así. Es bueno usando las herramientas como AutoCAD y SolidWorks, pero cuando explica no deja todo en claro y va super rápido. No suele paciencia con algunos estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2026-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'bafa453b8f478189c19e1e5cb71ed8ebc404f028b790469a4d3552027baf0437'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'El mejor profe de dibujo tecnico siendo una materia tan pesada el la hace mucho más accesible, no califica duro y en clase trata de explicar todo lo posible para que uno vaya a los examenes con todo claro a lo que va a hacer'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '198e0065b34c8d0b804bdd1b541677734e17324ea8fd0bed6bba089715f40632'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Un excelente profesor para dibujo tecnico, es un curso que no es fácil definitivamente!! explica con claridad y sin dar mucha teoría, explica lo que realmente importa. Su horario es un poco pesado pero vale definitivamente la pena si quiere pasar dibujo tecnico a la primera. Pd: le gusta meter miedo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'a0945745f2206e5273d1bb266896102cc6799a70f99dc98956bb4dd6c06197b7'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'El profe es demasiado buena nota, me hablaron que el curso de Dibujo era muy difícil pero con él fue super fácil, explica tan bien que desde el inicio logre comprender los programas, a mis compañeros que les costaba un poco, era muy amable y les explicaba muy gentilmente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-10T00:00:00+00:00'::TIMESTAMPTZ, '6bb9ea889056acd9130722c615685d1ac367d65c0042e9ecb229a0105fb46b12'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'el curso no es facil pero el hace que muchas cosas se faciliten y ayuda mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2eb2ea89a6ba0dc186d5ba38cd9c8acf67e5271c2484a2c3186b2f1928214363'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Matricule sin miedo, hace un curso tan difícil como lo es dibujo técnico, bastante accesible. Los exámenes los califica muy suave y ayuda bastante en la tareas y proyectos. Es un grande.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1732a10023fc7db2b5cbbeb34bf5f07431f277754aa7c8b755025f13b48c6b07'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'La "dificultad" del curso es por la cátedra, pero el profe es bastante bueno, tiene bastante conocimiento y siempre ayuda.A veces cuesta que responda los mensajes del grupo o por privado, pero en general muy buen profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '246299794133d42275a45d3d952c1950201fbb5bd0c4bd0a0f3ad61c029c668e'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Los de catedra se volvieron locos con las tareas este semestre, por eso se dificultó mucho la materia. Pero el profe es un amor, explica super bien y cualquier duda con gusto le responde.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0b9d9f6fa821b9db10a16c79524fd1da193e90e7dc64097dfc1015bd3b1fddc5'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Le gusta explicar y lo hace demasiado bien. Genera confianza, es imposible terminar una clase con dudas, no le importa caminar kilómetros en el aula con tal de explicar o incluso fuera de consulta ayuda. El mejor profe de América y me toco con el mejor asistente (Lewis)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '68def070724b93e79b4a6942c318ebc08869b406a685416a65272c0efad3864e'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Dibujo Técnico es una materia conocida por ser difícil y que gasta mucho tiempo. Sin embargo este profesor es muy bueno en su trabajo, al explicar hasta lo más difícil del curso de una manera clara y coherente. 100% de efectividad, además de que es buena nota y enseña bien. Muy Recomendado'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '963c3deadfaa95f93a244571269862d6365fe74273970ab104f911bebab2fe08'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Si no sabe nada de dibujo técnico, definitivamente debería matricular con el, explica todo hasta las cosas y se preocupa por que los estudiantes entiendan de verdad, la materia en si es un toque difícil pero con el se hace fácil, ayuda mucho con las tareas y en los exámenes también.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-04-25T00:00:00+00:00'::TIMESTAMPTZ, '847510ff57fb9780c241b3184df4afa879e31c79ea8fc6d3f6693c4eaba06faa'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Muy buen profe, perfecto para llevar dibujo por primera vez, eso sí prepárese para hacer muchas prácticas en clase y no da mucha teoría solo lo necesario, lo demás es practica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-14T00:00:00+00:00'::TIMESTAMPTZ, '7c8acddcf5227d3124a0e2770f4e3c6f83375bffb1e8894042965ba7df917639'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'El mejor profesor para llevar DT, se empeña en enseñar aspectos importantes para el futuro y lo hace de una manera excelente, algunas veces puede ir algo rápido, pero siempre que tengas una duda te la va aclarar con gusto. Lo que recomiendo es que escojan muy bien a sus compañeros para el proyecto.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, '63b71594e7bc835bdf9507f3ea853bae89e52dee4cd59505177b6a73d9ac86e1'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Literalmente no hay mejor profesor que Maximino, ni aunque un profesor le regale a usted 100 millones, supera como profesor a Maximino, si puede matricular con él HAGALO, no va a encontrar mejor profesor en toda su carrera, tiene pasión por lo que hace y se nota en su forma de explicar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-16T00:00:00+00:00'::TIMESTAMPTZ, '79c76bf8c8e3b9397cf2c2876e29c50e5493b795a797099467f2b87557c67e73'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Maximino es lo de lo mejor que hay, enseña un poco rápido pero es muy buen profe, repite las veces que sean necesarias y enseña muchas cosas extras que son demasiado útiles, uno va adelantado siempre y preparado para los exámenes. Como persona es muy buena gente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-09T00:00:00+00:00'::TIMESTAMPTZ, 'e69ab89129d808f6ca863fe86456a0628b5c9fe4f9d4507dc49a30f9992807ac'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'El profe es demasiado buena nota y le interesa que la gente pase, los trabajos que deja son faciles; eso si, deja un proyecto final grupal... Pero igualmente queda recomendadisimo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'f5cc73e364a6eedf317fddb5f790c88f2298236bcdc6c1826d264d80e17a8f22'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Buen profe, el trabajo final es largo pero da suficiente ayuda para poder hacerlo bien, responde consultas y sus tareas son relativamente fáciles, durante los exámenes esta ahí para ayudar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'de4a1547c11eb1c96b8c0f533aad33697a7902b4c011146af3fc539bf8c6be4b'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'El mejor profe para llevar DT, explica muy claro, es muy buena nota, se preocupa porque los entiendan, resuelve dudas, sin duda alguna uno de los mejores profes que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd51db0cb78475259e6ac779548e15d52427acceff780c6fc4552950f8e911224'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Excelente profesor. Matricule sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ad04356020e58e47f22df5e37c84423023e040d811d4d066e823918f9153b66e'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'f113734a6f6a06ac476eea902ebc94f46c51168bad588d118c2b0f2a6b63b48f'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Por la virtualidad es poco difícil al principio pero el profe se esfuerza en que uno entienda. Tambien es muy accesible en horario de consultas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'dc64abfc91298fde76f82695451b7aa4f0827129864898553a06a8134a705a10'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'El profe explica bien, solo que por ser virtual se vuelve un aprendizaje muy independiente, si hace todos los trabajos pasa, y dura mucho en calificar sería lo único malo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '16d14af84b7a98b58fbfa6e31edf79743a03d057a57ba2025a31d7bc61e0f31a'::TEXT, ARRAY[610]::BIGINT[]),
    (230::BIGINT, 'Se las juega bastante con Solid, hay que poner atención para no perderle el hilo a la clase, aunque retoma cuando sea necesario.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-02-17T00:00:00+00:00'::TIMESTAMPTZ, 'f3dd59f496b5c4c6dbb4ff2b9dd6293a9a050ebec2fced140a5bb2df7668dc9f'::TEXT, ARRAY[610]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
